class Solution {
public:
    int findPairs(vector<int>& nums, int k) {
        map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        int pairs = 0;
        for (auto& [v, c] : cnt) {
            int want = v + k;
            if (k == 0) pairs += c > 1;
            else if (cnt.count(want)) pairs++;
        }
        return pairs;
    }
};
